/* BATTLE BEAVER — Carbon Edition / PlayStation 4 — Version 9 (responsive trigger and bumper feedback)
   GamePad Viewer skin override for https://app.gpv.gg/?p=1&s=5
   IMPORTANT: Put the RAW URL of THIS FILE in "Edit CSS URL" (editcss=).
   Leave "Custom CSS URL" empty. Do not combine with older versions.
   Preserves the built-in DS4 position/shape and input state updates.
   Uses the default responsive DS4 hitboxes; no controller translation or resizing.
*/

/* Deeper neutral-black and polished silver 2-over-2 carbon twill across both shells,
   with circular neutral-charcoal socket covers replacing the remaining navy rims.
   This overlay is exactly 806 x 598 pixels: NO scaling, offsets or transforms.
   The source image's alpha excludes the D-pad, buttons, sticks and touchpad.
   Texture is embedded so GitHub Raw is the only URL the skin needs. */
.controller.ds4 { isolation: isolate; }
.controller.ds4::before {
  content: '';
  position: absolute;
  left: 0; top: 0;
  width: 806px; height: 598px;
  z-index: 0;
  pointer-events: none;
  background: url('data:image/png;base64,') 0 0 / 806px 598px no-repeat;
}
/* Native children already have correct absolute coordinates; do NOT alter them. */
.controller.ds4 > .triggers,
.controller.ds4 > .bumpers,
.controller.ds4 > .arrows,
.controller.ds4 > .dpad,
.controller.ds4 > .abxy,
.controller.ds4 > .sticks,
.controller.ds4 > .meta,
.controller.ds4 > .touchpad { z-index: 2; }

/* The resting shoulders are part of the default SVG base, and active
   sprites are normally transparent. White base silhouettes below preserve
   the existing analog trigger/bumper layers above them. */
.controller.ds4 .triggers,
.controller.ds4 .bumpers { isolation: isolate; }
.controller.ds4 .triggers::before,
.controller.ds4 .triggers::after {
  position: absolute;
  top: 0;
  width: 99px;
  height: 90px;
  box-sizing: border-box;
  z-index: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  padding-top: 30px;
  pointer-events: none;
  color: #333;
  font: 700 14px Arial, sans-serif;
  text-shadow: 0 1px 0 rgba(255,255,255,.7);
  background: linear-gradient(150deg,#fff 5%,#f5f5f5 58%,#c6c6c6 100%);
  clip-path: polygon(0% 98%, 5% 65%, 12% 36%, 21% 15%, 34% 3%, 47% 0%, 60% 1%, 74% 10%, 86% 27%, 96% 63%, 100% 98%);
  box-shadow: inset 0 -4px 1px #7d838a;
}
.controller.ds4 .triggers::before { content: 'L2'; left: 0; }
.controller.ds4 .triggers::after  { content: 'R2'; right: 0; }
.controller.ds4 .triggers .trigger { position: relative; z-index: 2; filter: grayscale(1) invert(1) brightness(1.9); }

.controller.ds4 .bumpers::before,
.controller.ds4 .bumpers::after {
  content: '';
  position: absolute;
  width: 99px;
  height: 23px;
  top: 0;
  z-index: 0;
  pointer-events: none;
  border-radius: 15px 15px 5px 5px;
  background: linear-gradient(to bottom, #f9f9f9 0%, #dedede 75%, #aaaaaa 100%);
  box-shadow: inset 0 1px 1px rgba(255,255,255,.6), 0 1px 2px rgba(0,0,0,.3);
}
.controller.ds4 .bumpers::before { left: 0; }
.controller.ds4 .bumpers::after { right: 0; }
.controller.ds4 .bumpers .bumper { position: relative; z-index: 2; filter: grayscale(1) invert(1); }
.controller.ds4 .bumpers .bumper.pressed { filter: brightness(0); opacity: .25; }

/* White and unmarked face buttons — keep the four native 55px hit targets. */
.controller.ds4 .abxy .button {
  background: none !important;
  border: 0 !important;
  box-shadow: none !important;
  color: transparent !important;
  font-size: 0 !important;
}
/* Every disc is centered at 50%/50% of its original 55px GamePad Viewer hitbox. */
.controller.ds4 .abxy .button::after { content: none !important; }
.controller.ds4 .abxy .button::before {
  content: '' !important;
  position: absolute;
  left: 50%; top: 50%;
  transform: translate(-50%, -50%);
  width: 43px; height: 43px;
  box-sizing: border-box;
  border-radius: 50%;
  background: radial-gradient(circle at 40% 33%, #fff 0%, #f7f7f7 57%, #dfdfdf 83%, #c5c5c5 100%);
  border: 2px solid #121212;
  box-shadow: 0 2px 3px rgba(0,0,0,.67), inset 0 1px 1px #fff;
  pointer-events: none;
}
.controller.ds4 .abxy .button.pressed::before { filter: brightness(.65); }

/* Keep EXACT PS4 D-pad artwork and geometry. Tint the original sprite rather
   than creating rectangular replacement buttons or altering hit areas. */
.controller.ds4 .dpad .face {
  filter: grayscale(1) brightness(0) invert(.96) drop-shadow(0 1px 1px rgba(0,0,0,.48));
}
.controller.ds4 .dpad .face.pressed {
  filter: grayscale(1) brightness(0) invert(.65) drop-shadow(0 1px 1px #090909);
}

/* Centered round black stick tops, moving with the original responsive elements. */
.controller.ds4 .sticks .stick {
  -webkit-mask: none !important;
  mask: none !important;
  border-radius: 50% !important;
  background: radial-gradient(circle at 50% 47%, #1a1a1a 0 42%, #101010 48% 58%, #080808 64%, #252525 67%, transparent 71%) !important;
  box-shadow: none !important;
  filter: none !important;
}
.controller.ds4 .sticks .stick.pressed { filter: brightness(1.55) !important; }

/* Unmarked SHARE/OPTIONS — white pill buttons, no extra writing.
   Original words are printed in the base SVG; tiny dark patches cover them. */
.controller.ds4 .arrows::before,
.controller.ds4 .arrows::after {
  content: '';
  position: absolute;
  top: -5px;
  width: 50px;
  height: 14px;
  z-index: 1;
  pointer-events: none;
  border-radius: 3px;
  background: #101010;
}
.controller.ds4 .arrows::before { left: -4px; }
.controller.ds4 .arrows::after { right: -4px; }
.controller.ds4 .arrows .back,
.controller.ds4 .arrows .start {
  opacity: 1 !important;
  position: relative;
  z-index: 2;
  background: linear-gradient(110deg,#ffffff,#e0e0e0) !important;
  border-radius: 14px;
  box-shadow: inset 0 1px 1px rgba(255,255,255,.85),0 1px 1px #08090b;
}
.controller.ds4 .arrows .back.pressed,
.controller.ds4 .arrows .start.pressed { filter: brightness(.58); }

/* Leave the PS logo AND home button exactly as the built-in skin draws them. */

/* Small gold Battle Beaver text on the black lower center panel, immediately
   above the headset-jack detail. No text below or outside the controller. */
.controller.ds4::after {
  content: 'BATTLE BEAVER';
  position: absolute;
  top: 404px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 6;
  pointer-events: none;
  color: #d8ad52;
  white-space: nowrap;
  font: 800 10px/1.1 Arial, Helvetica, sans-serif;
  letter-spacing: .65px;
  text-shadow: 0 1px 1px #000, 0 0 2px rgba(187,132,37,.32);
}


/* ─── VERSION 9 / SHOULDER AND BUTTON FEEDBACK ──────────────────────────
   The white trigger and bumper covers are static *resting* artwork. Actual
   GamePad Viewer input sprites render over them in a dark gradient. The
   analog trigger element MUST NOT have opacity:0!important, since GPV
   updates its opacity as the trigger is squeezed. Do not translate or
   resize the original DS4 input containers. */

/* Resting triggers: symmetric white shells matching the 99px original
   trigger positions. Keep the original L2/R2 labels. */
.controller.ds4 .triggers::before,
.controller.ds4 .triggers::after {
  opacity: 1 !important;
  width: 101px;
  height: 91px;
  top: -1px;
  background: linear-gradient(150deg, #fff 6%, #f6f6f6 64%, #d3d3d3 100%);
  clip-path: polygon(0% 100%, 0% 88%, 3% 61%, 9% 34%, 19% 13%, 31% 3%, 44% 0%, 56% 0%, 69% 4%, 81% 16%, 91% 36%, 97% 67%, 100% 90%, 100% 100%);
  box-shadow: none;
}
.controller.ds4 .triggers::before {left: -1px;}
.controller.ds4 .triggers::after  {right: -1px;}

/* Animated input layer. GPV changes the element's inline opacity from 0
   toward 1 with trigger travel; leaving it non-!important is essential.
   The dark overlay fills the exact trigger silhouette, bounded by the
   original white border. No overlays are moved out of alignment. */
.controller.ds4 .triggers .trigger {
  opacity: 0;
  position: relative;
  z-index: 3;
  width: 99px;
  height: 90px;
  border: 0;
  filter: none !important;
  background: linear-gradient(155deg, #4d4d4d 0%, #292929 55%, #111111 100%) !important;
  background-image: linear-gradient(155deg, #4d4d4d 0%, #292929 55%, #111111 100%) !important;
  clip-path: polygon(0% 100%, 0% 88%, 3% 61%, 9% 34%, 19% 13%, 31% 3%, 44% 0%, 56% 0%, 69% 4%, 81% 16%, 91% 36%, 97% 67%, 100% 90%, 100% 100%);
  box-shadow: none !important;
}
/* Fallback for gamepads or GPV versions which use a .pressed class. */
.controller.ds4 .triggers .trigger.pressed {
  opacity: 1 !important;
}

/* L1 and R1 rest white. When their native elements receive .pressed,
   render visible dark charcoal directly over those white bumpers. */
.controller.ds4 .bumpers .bumper {
  z-index: 3;
  position: relative;
  background: linear-gradient(180deg, #4f4f4f 0%, #252525 55%, #0b0b0b 100%) !important;
  background-image: linear-gradient(180deg, #4f4f4f 0%, #252525 55%, #0b0b0b 100%) !important;
  border-radius: 15px 15px 5px 5px;
  box-shadow: inset 0 1px 1px rgba(255,255,255,.28) !important;
  filter: none !important;
  opacity: 0;
}
.controller.ds4 .bumpers .bumper.pressed {
  filter: none !important;
  opacity: 1 !important;
}

/* Retain Version 8's high-contrast pressed feedback everywhere else. */
.controller.ds4 .abxy .button.pressed::before {
  background: radial-gradient(circle at 40% 35%, #303030 0%, #171717 60%, #0c0c0c 100%) !important;
  border-color: #dadada !important;
  box-shadow: inset 0 1px 3px #050505, 0 0 1px #ffffff !important;
  filter: none !important;
}
.controller.ds4 .dpad .face.pressed {
  filter: grayscale(1) brightness(0) invert(.17) drop-shadow(0 1px 1px #000) !important;
}
.controller.ds4 .arrows .back.pressed,
.controller.ds4 .arrows .start.pressed {
  background: linear-gradient(110deg, #343434, #151515) !important;
  box-shadow: inset 0 1px 2px #000, 0 0 1px #fff !important;
  filter: none !important;
}
.controller.ds4 .sticks .stick.pressed {
  background: radial-gradient(circle at 45% 36%, #777 0%, #5d5d5d 40%, #313131 58%, #171717 70%, transparent 73%) !important;
  box-shadow: inset 0 1px 4px rgba(255,255,255,.22), 0 0 3px rgba(240,240,240,.37) !important;
  filter: none !important;
}
